function IconButton({ children, title='操作', onClick, active }) {
  return <button type="button" aria-label={title} className={`icon-btn ${active ? 'active' : ''}`} title={title} onClick={onClick}>{children}</button>;
}

function Toast({ text }) {
  return text ? <div className="toast" role="status" aria-live="polite"><Check size={15} />{text}</div> : null;
}

const isMissingApiError=message=>/未配置|缺少.*key|api key|尚无可用密钥|provider/i.test(String(message||''));
const waitWithAbort=(delay,signal)=>new Promise((resolve,reject)=>{const timer=window.setTimeout(resolve,delay);if(!signal)return;const stop=()=>{window.clearTimeout(timer);reject(Object.assign(new Error('请求已取消'),{name:'AbortError'}))};if(signal.aborted)return stop();signal.addEventListener('abort',stop,{once:true})});
